package com.jl.smallchange_.oop;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Scanner;
/ 该类是完成零钱通的各个功能的类 使用OOP(面向对象编程) 将各个功能对应一个方法 显示菜单 零钱通明细 /
public class SmallChangeOOP { Scanner scanner = new Scanner(System.in);// 新建扫描器 String details = "\n----====\t零钱通明细\t====----\n"; double money = 0; double balance = 0; boolean loop = true; Date date = null; SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd hh-mm");// 用于日期格式化 String note = ""; public void mainMenu() { System.out.println("显示零钱通菜单"); do { System.out.println("----====\t零钱通菜单\t====----\n" + "\t1.零钱通明细\n" + "\t2.收益入账\n" + "\t3.消费\n" + "\t4.退出\n" + "请选择(1-4):"); // 扫描器请求输入 String s = scanner.nextLine(); switch (s) { case "1": // 执行功能零钱通明细,使用Account类中的showCheck this.detail(); break; case "2": this.income(); break; case "3": this.pay(); break; case "4": this.quit(); break; } } while (loop); System.out.println("退出了零钱通..........."); } public void detail() { System.out.println(details); System.out.println(); } public void income() { // 执行入账,使用Earns类中的方法 System.out.print("请输入入账金额:"); money = scanner.nextDouble(); scanner.nextLine(); // 判断输入金额是否正确 if (money balance) { System.out.println("消费金额应该在(0-" + balance + ")"); return; } System.out.println("消费说明..."); note = scanner.nextLine(); balance -= money; date = new Date(); details += "\n" + note + "\t" + "-" + money + "\t" + sdf.format(date) + "\t" + balance; } public void quit() { String sQuit; while (true) { // 定义一个变量接收输入 // 使用while和break处理接收到的这个输入是Y或者N System.out.println("确认退出零钱通(Y/N)"); sQuit = scanner.nextLine(); // if (sQuit.equals("Y") || sQuit.equals("N")) { // break; // } if (sQuit.equals("Y")) { System.out.println("成功退出,再见!"); loop = false; break; } else if (sQuit.equals("N")) { break; } } } //...
} java
